// Ricerca sedi: filtra la tendina senza alterare la sede già selezionata.
function bindPointOfSaleSearch(searchId,selectId){
 const input=$(searchId),select=$(selectId);if(!input||!select)return;
 const options=[...select.options].map(o=>({value:o.value,label:o.textContent}));
 input.addEventListener('input',()=>{
  const q=input.value.toLocaleLowerCase('it').trim(),selected=select.value;
  select.replaceChildren();
  const matches=options.filter(o=>!q||!o.value||o.label.toLocaleLowerCase('it').includes(q));
  for(const entry of matches){const option=new Option(entry.label,entry.value);option.selected=entry.value===selected;select.add(option)}
  if(selected&&!matches.some(o=>o.value===selected)){
   const prior=options.find(o=>o.value===selected);if(prior){const option=new Option(prior.label,prior.value);option.selected=true;select.add(option)}
  }
 });
}
