export function bindHomeQuickActions(){document.querySelectorAll('[data-home-go]').forEach(b=>b.onclick=()=>go(b.dataset.homeGo))}


export function renderLowStockPage(){
  const box=$('#lowStockPageList'),count=$('#lowStockCount');if(!box)return;
  const q=($('#lowStockSearch')?.value||'').toLowerCase().trim();
  const max=Number(state.settings.lowStockMax??5);
  const arr=activeProducts().filter(p=>{const qty=productQty(p);const txt=`${p.name||''} ${p.brand||''} ${p.barcode||''}`.toLowerCase();return qty<=max&&txt.includes(q)}).sort((a,b)=>productQty(a)-productQty(b));
  if(count)count.textContent=arr.length;
  const v=$('#lowStockPageSize')?.value||'25';const limit=v==='all'?Infinity:Math.max(1,Number(v)||25);const list=arr.slice(0,limit);
  box.innerHTML=list.map(p=>{const qty=productQty(p);return `<button type="button" class="stock-card low-stock-page-card" data-low-stock-product="${esc(p.id)}">${thumb(p,'stock-photo')}<div><b>${esc(p.name||'Prodotto')}</b><small>${esc(p.brand||'')} · ${esc(p.size||p.format||'')}</small><span class="pill ${qty<=0?'badge-danger':qty<=2?'badge-warn':'badge-ok'}">${qty} pz</span></div></button>`}).join('')||'<div class="empty">Nessun prodotto con scorta bassa.</div>';
  document.querySelectorAll('[data-low-stock-product]').forEach(b=>b.onclick=()=>openProduct(state.products.find(p=>String(p.id)===String(b.dataset.lowStockProduct))));
}

let stockWarehouseFilterIds=[];
function stockSelectedWarehouses(){const all=warehouses();if(!stockWarehouseFilterIds.length)stockWarehouseFilterIds=all.map(w=>String(w.id));const valid=new Set(all.map(w=>String(w.id)));stockWarehouseFilterIds=stockWarehouseFilterIds.filter(id=>valid.has(String(id)));if(!stockWarehouseFilterIds.length)stockWarehouseFilterIds=all.map(w=>String(w.id));return all.filter(w=>stockWarehouseFilterIds.includes(String(w.id)))}
function renderStockWarehouseFilters(){const box=$('#stockWarehouseFilters');if(!box)return;const all=warehouses(),selected=stockSelectedWarehouses(),allSelected=selected.length===all.length;box.innerHTML=`<label class="warehouse-filter-option warehouse-filter-all"><input type="checkbox" data-stock-wh-all ${allSelected?'checked':''}><span>Tutti i magazzini</span></label>${all.map(w=>`<label class="warehouse-filter-option"><input type="checkbox" data-stock-wh="${esc(w.id)}" ${stockWarehouseFilterIds.includes(String(w.id))?'checked':''}><span>${esc(w.name)}</span></label>`).join('')}`;const allBox=box.querySelector('[data-stock-wh-all]');if(allBox)allBox.onchange=()=>{stockWarehouseFilterIds=allBox.checked?all.map(w=>String(w.id)):[];if(!stockWarehouseFilterIds.length)stockWarehouseFilterIds=[String(all[0]?.id||'')].filter(Boolean);renderStock()};box.querySelectorAll('[data-stock-wh]').forEach(ch=>ch.onchange=()=>{const id=String(ch.dataset.stockWh);if(ch.checked){if(!stockWarehouseFilterIds.includes(id))stockWarehouseFilterIds.push(id)}else stockWarehouseFilterIds=stockWarehouseFilterIds.filter(x=>x!==id);if(!stockWarehouseFilterIds.length){ch.checked=true;stockWarehouseFilterIds=[id];toast('Mantieni almeno un magazzino selezionato.')}renderStock()})}
export function renderStock(){
  renderStockWarehouseFilters();
  const selected=stockSelectedWarehouses(),selectedIds=selected.map(w=>String(w.id));
  const q=($('#stockSearch')?.value||'').toLowerCase(),f=$('#stockFilter')?.value||'all',max=Number(state.settings.lowStockMax??5);
  const arr=state.products.filter(p=>p.deleted!==true&&selectedIds.some(id=>!productDeletedInWarehouse(p,id))).filter(p=>{const qtys=selectedIds.filter(id=>!productDeletedInWarehouse(p,id)).map(id=>productQty(p,id)),matchLow=qtys.some(q=>q<=max),matchZero=qtys.some(q=>q<=0);return `${p.name||''} ${p.brand||''} ${p.category||''} ${p.size||p.format||''} ${(Array.isArray(p.notes)?p.notes:(typeof p.notes==='string'?p.notes.split(/\n|,|;/):[])).join(' ')}`.toLowerCase().includes(q)&&(f==='all'||(f==='low'&&matchLow)||(f==='zero'&&matchZero))}).slice(0,pageSize('#stockPageSize'));
  $('#stockGrid').innerHTML=arr.map(p=>{const rows=selected.map(w=>productDeletedInWarehouse(p,w.id)?`<div class="warehouse-stock-row is-removed"><span>${esc(w.name)}</span><b>Rimosso</b></div>`:`<div class="warehouse-stock-row"><span>${esc(w.name)}</span><b>${productQty(p,w.id)} pz</b></div>`).join('');const total=selected.reduce((a,w)=>a+(productDeletedInWarehouse(p,w.id)?0:productQty(p,w.id)),0);return `<div class="stock-card multi-warehouse-stock-card">${thumb(p,'stock-photo')}<div class="stock-card-body"><h3>${esc(p.name||'Prodotto')}</h3><p>${esc(p.brand||'')} · ${esc(p.size||p.format||'')}</p>${selected.length>1?`<div class="stock-kpi">${total} <small>pz totali</small></div>`:''}<div class="warehouse-stock-breakdown">${rows}</div><div class="actions"><button class="btn secondary compact-btn" data-stock-open="${esc(p.id)}">Apri</button></div></div></div>`}).join('')||'<div class="empty">Nessun prodotto.</div>';
  document.querySelectorAll('[data-stock-open]').forEach(b=>b.onclick=()=>openProduct(state.products.find(p=>String(p.id)===b.dataset.stockOpen)));
  renderStockMovements(selectedIds)
}

let stockMoveProductId='';
let stockMoveCompleted=null;
let stockMoveSubmitting=false;
export function openStockMove(productId=''){stockMoveProductId=productId||'';stockMoveCompleted=null;stockMoveSubmitting=false;go('stock-move');renderStockMove()}
export function openStockTransfer(){const whs=warehouses();if(whs.length<2)return toast('Crea almeno due magazzini nelle Impostazioni.');openModal('Trasferisci prodotto tra magazzini',`<form id="stockTransferForm" class="form-grid"><label class="full">Prodotto<select id="transferProduct">${activeProducts().map(p=>`<option value="${esc(p.id)}">${esc(p.name||'Prodotto')}</option>`).join('')}</select></label><label>Da<select id="transferFrom">${whs.map(w=>`<option value="${esc(w.id)}" ${w.id===effectiveWarehouseId()?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label>A<select id="transferTo">${whs.map((w,i)=>`<option value="${esc(w.id)}" ${i===1?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label>Quantità<input id="transferQty" type="number" min="1" step="1" value="1"></label><label>Nota<input id="transferNote" value="Trasferimento interno"></label><div class="full" id="transferAvailability"></div><div class="full"><button class="btn primary">Conferma trasferimento</button></div></form>`);const refresh=()=>{const p=state.products.find(x=>String(x.id)===String($('#transferProduct').value));const from=$('#transferFrom').value,to=$('#transferTo').value;$('#transferAvailability').innerHTML=`<div class="transfer-preview"><span>${esc(warehouseById(from)?.name||from)}: <b>${productQty(p,from)} pz</b></span><span>${esc(warehouseById(to)?.name||to)}: <b>${productQty(p,to)} pz</b></span></div>`};['#transferProduct','#transferFrom','#transferTo'].forEach(id=>$(id).onchange=refresh);refresh();$('#stockTransferForm').onsubmit=async e=>{e.preventDefault();try{await transferStock($('#transferProduct').value,$('#transferFrom').value,$('#transferTo').value,Number($('#transferQty').value),$('#transferNote').value.trim()||'Trasferimento interno');closeModal();toast('Trasferimento completato.')}catch(err){toast(err.message||'Errore trasferimento.')}}}
export function renderStockMove(){
  // Do not destroy the form and its input focus when product snapshots arrive during a transaction.
  if(stockMoveSubmitting)return;
  const root=$('#stockMoveContent');if(!root)return;const p=activeProducts().find(x=>String(x.id)===String(stockMoveProductId));
  root.innerHTML=`<div class="stock-operation-shell"><div class="stock-operation-search"><label>Barcode o nome prodotto<input id="stockMoveBarcode" class="scan-input compact-scan" type="search" autocomplete="off" placeholder="Incolla barcode oppure digita il nome"></label><div id="stockMoveResults" class="stock-picker-list"></div></div><div id="stockMoveSelected" class="stock-operation-selected">${p?stockMoveSelectedHtml(p):'<div class="empty">Seleziona o scansiona un prodotto per iniziare.</div>'}</div></div>`;
  const refresh=()=>{const q=($('#stockMoveBarcode').value||'').toLowerCase().trim();const arr=(q?activeProducts().filter(x=>`${x.name||''} ${x.brand||''} ${x.barcode||''}`.toLowerCase().includes(q)):activeProducts()).slice(0,20);$('#stockMoveResults').innerHTML=arr.map(x=>`<button type="button" class="stock-picker-row" data-stock-pick="${esc(x.id)}">${thumb(x,'mini-thumb')}<span><b>${esc(x.name||'Prodotto')}</b><small>${esc(x.brand||'')} · ${productQty(x)} pz</small></span></button>`).join('')};
  refresh();
  $('#stockMoveResults').onclick=e=>{const b=e.target.closest('[data-stock-pick]');if(!b)return;stockMoveProductId=b.dataset.stockPick;stockMoveCompleted=null;renderStockMove()};
  $('#stockMoveBarcode').oninput=e=>{const v=e.target.value.trim();const found=v?activeProducts().find(x=>String(x.barcode||'').trim()===v):null;if(found&&String(found.id)!==String(stockMoveProductId)){stockMoveProductId=found.id;stockMoveCompleted=null;renderStockMove();return}refresh()};
  if(p&&!stockMoveCompleted)bindStockMoveForm(p);
  if(p&&stockMoveCompleted){const again=$('#stockMoveAgain');if(again)again.onclick=()=>{stockMoveCompleted=null;renderStockMove()}}
}
function stockMoveSelectedHtml(p){
  const whs=warehouses(),current=effectiveWarehouseId(),done=stockMoveCompleted&&String(stockMoveCompleted.productId)===String(p.id)?stockMoveCompleted:null;
  if(done)return `<div class="selected-product-card">${thumb(p,'stock-photo')}<div><span>Operazione completata</span><h3>${esc(p.name||'Prodotto')}</h3><p>${esc(p.brand||'')} · ${esc(p.size||p.format||'')}</p><strong>${esc(done.warehouseName)}</strong></div></div><div class="stock-move-receipt" role="status" aria-live="polite"><h3>${done.delta>0?'Carico':'Scarico'} registrato correttamente</h3><div class="stock-move-receipt-numbers"><div><small>Prima</small><b>${done.before}</b></div><div><small>${done.delta>0?'Caricati':'Scaricati'}</small><b>${done.delta>0?'+':''}${done.delta}</b></div><div><small>Dopo</small><b>${done.after}</b></div></div><p>Movimento salvato su ${esc(done.warehouseName)}. ${done.online?'La sincronizzazione verso Shopify è stata richiesta; l’aggiornamento remoto può richiedere qualche istante.':''}</p></div><div class="stock-move-after-actions"><button type="button" class="btn secondary" id="stockMoveAgain">Nuova operazione sul prodotto</button><p>Per lavorare su un altro articolo, cercalo o scansionalo qui a sinistra.</p></div>`;
  return `<div class="selected-product-card">${thumb(p,'stock-photo')}<div><span>Prodotto selezionato</span><h3>${esc(p.name||'Prodotto')}</h3><p>${esc(p.brand||'')} · ${esc(p.size||p.format||'')}</p><strong id="stockMoveCurrentQty">${productQty(p,current)} pz disponibili in ${esc(warehouseById(current)?.name||'magazzino')}</strong></div></div><form id="stockOperationForm" class="stock-operation-form"><label class="full">Magazzino<select id="stockOperationWarehouse">${whs.map(w=>`<option value="${esc(w.id)}" ${String(w.id)===String(current)?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label>Operazione<select id="stockOperationType"><option value="load">Carico</option><option value="unload">Scarico</option></select></label><label>Quantità<input id="stockOperationQty" type="number" min="1" step="1" value="1" required></label><label class="full">Nota<input id="stockOperationNote" value="Carico merce"></label><div class="full"><button class="btn primary" id="stockOperationSubmit">Conferma carico</button></div></form>`
}
function bindStockMoveForm(p){
 const type=$('#stockOperationType'),note=$('#stockOperationNote'),btn=$('#stockOperationSubmit'),wh=$('#stockOperationWarehouse');
 const sync=()=>{const load=type.value==='load';note.value=load?'Carico merce':'Scarico merce';btn.textContent=load?'Conferma carico':'Conferma scarico';btn.className='btn '+(load?'primary':'danger');const wid=wh.value;const q=$('#stockMoveCurrentQty');if(q)q.textContent=`${productQty(p,wid)} pz disponibili in ${warehouseById(wid)?.name||'magazzino'}`};type.onchange=sync;wh.onchange=sync;sync();
 $('#stockOperationForm').onsubmit=async e=>{
   e.preventDefault();if(stockMoveSubmitting||stockMoveCompleted)return;
   const wid=wh.value,amount=Number($('#stockOperationQty').value),delta=(type.value==='load'?1:-1)*amount;
   if(!Number.isSafeInteger(amount)||amount<1){toast('Inserisci una quantità intera maggiore di zero.');return}
   stockMoveSubmitting=true;btn.disabled=true;btn.textContent='Salvataggio...';
   try{
     const result=await updateStock(p.id,delta,note.value.trim(),wid);
     const before=Number(result?.qtyBefore),after=Number(result?.qtyAfter);
     if(!Number.isFinite(before)||!Number.isFinite(after))throw new Error('Movimento salvato, ma riepilogo non disponibile: verifica lo storico prima di ripetere.');
     stockMoveCompleted={productId:String(p.id),warehouseName:warehouseById(wid)?.name||wid,delta,before,after,online:String(warehouseById(wid)?.name||'').toLowerCase()==='online'};
     toast('Movimento registrato.');
   }catch(err){toast(err.message||'Errore magazzino.');if(stockMoveCompleted===null)btn.disabled=false}
   finally{stockMoveSubmitting=false;if(stockMoveCompleted)renderStockMove();else{btn.disabled=false;sync()}}
 }
}
function renderStockMovements(selectedIds=[]){const box=$('#stockMovements');if(!box)return;const selected=new Set((selectedIds||[]).map(String));const arr=(state.stockMovements||[]).filter(m=>!selected.size||selected.has(String(m.warehouseId||''))||selected.has(String(m.fromWarehouseId||''))||selected.has(String(m.toWarehouseId||''))).slice(0,40);box.innerHTML=arr.map(m=>`<div class="list-row"><div><b>${m.operation==='transfer'?'Trasferimento':(m.operation==='reset'?'Reset stock':(m.operation==='unload'?'Scarico':'Carico'))} · ${esc(m.productName||'Prodotto')}</b><small>${m.operation==='transfer'?`${esc(m.fromWarehouseName||'')} → ${esc(m.toWarehouseName||'')} · `:`${esc(m.warehouseName||'')} · `}${fmtDate(m.createdAtClient||m.createdAt)} · ${esc(m.userName||m.email||'')}</small></div><span class="pill ${m.operation==='transfer'?'':' '+(Number(m.delta)<0?'badge-warn':'badge-ok')}">${m.operation==='transfer'?('→ '+Number(m.qty||0)+' pz'):((Number(m.delta)>0?'+':'')+Number(m.delta||0))}</span></div>`).join('')||'<div class="empty">Nessun movimento recente.</div>'}

export function openBulkStockManager(){
  go('stock-bulk');
  renderBulkStockManager();
}

let bulkStockSelected=new Set();
export function renderBulkStockManager(){
  const root=$('#bulkStockPageContent');if(!root)return;
  const whs=warehouses();
  if(!whs.length){root.innerHTML='<div class="empty">Nessun magazzino configurato.</div>';return}
  const current=effectiveWarehouseId();
  root.innerHTML=`<div class="bulk-stock-page"><div class="bulk-stock-controls"><label>Magazzino<select id="bulkStockWarehouse">${whs.map(w=>`<option value="${esc(w.id)}" ${String(w.id)===String(current)?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label>Operazione<select id="bulkStockOperation"><option value="reset">Azzera a 0</option><option value="unload">Scarica quantità</option><option value="load">Carica quantità</option></select></label><label id="bulkStockQtyLabel">Quantità<input id="bulkStockQty" type="number" min="1" step="1" value="1"></label><label class="full">Cerca prodotto<input id="bulkStockSearch" placeholder="Nome, marca o barcode"></label><div class="bulk-stock-master full"><label><input id="bulkStockSelectAll" type="checkbox"> <span>Seleziona tutti i prodotti visibili</span></label><b id="bulkStockSelectedCount">0 selezionati</b></div></div><div id="bulkStockProducts" class="bulk-stock-products page-version"></div><div class="bulk-stock-footer page-version"><button type="button" id="bulkStockConfirm" class="btn danger">Azzera selezionati</button></div></div>`;
  const op=$('#bulkStockOperation'),qtyLabel=$('#bulkStockQtyLabel'),warehouse=$('#bulkStockWarehouse'),search=$('#bulkStockSearch'),list=$('#bulkStockProducts'),master=$('#bulkStockSelectAll'),counter=$('#bulkStockSelectedCount'),confirmBtn=$('#bulkStockConfirm');
  if(!op||!qtyLabel||!warehouse||!search||!list||!master||!counter||!confirmBtn)return;
  const visibleProducts=()=>{const q=(search.value||'').toLowerCase().trim(),wid=warehouse.value;return state.products.filter(p=>p.deleted!==true&&!productDeletedInWarehouse(p,wid)).filter(p=>`${p.name||''} ${p.brand||''} ${p.barcode||''}`.toLowerCase().includes(q))};
  const syncMaster=()=>{const ids=visibleProducts().map(p=>String(p.id));const checked=ids.length>0&&ids.every(id=>bulkStockSelected.has(id));master.checked=checked;master.indeterminate=!checked&&ids.some(id=>bulkStockSelected.has(id));counter.textContent=`${bulkStockSelected.size} selezionati`};
  const renderList=()=>{const wid=warehouse.value,arr=visibleProducts();list.innerHTML=arr.map(p=>`<label class="bulk-stock-row"><input type="checkbox" data-bulk-product="${esc(p.id)}" ${bulkStockSelected.has(String(p.id))?'checked':''}><span class="bulk-stock-product-main">${thumb(p,'mini-thumb')}<span><b>${esc(p.name||'Prodotto')}</b><small>${esc(p.brand||'')} · ${esc(p.barcode||'')}</small></span></span><strong>${productQty(p,wid)} pz</strong></label>`).join('')||'<div class="empty">Nessun prodotto.</div>';list.querySelectorAll('[data-bulk-product]').forEach(ch=>ch.onchange=()=>{const id=String(ch.dataset.bulkProduct);if(ch.checked)bulkStockSelected.add(id);else bulkStockSelected.delete(id);syncMaster()});syncMaster()};
  const syncOperation=()=>{const isReset=op.value==='reset';qtyLabel.classList.toggle('hidden',isReset);confirmBtn.className='btn '+(op.value==='load'?'primary':'danger');confirmBtn.textContent=isReset?'Azzera selezionati':(op.value==='load'?'Carica selezionati':'Scarica selezionati')};
  op.onchange=syncOperation;warehouse.onchange=renderList;search.oninput=renderList;master.onchange=()=>{visibleProducts().forEach(p=>master.checked?bulkStockSelected.add(String(p.id)):bulkStockSelected.delete(String(p.id)));renderList()};
  syncOperation();renderList();
  confirmBtn.onclick=async()=>{
    if(!bulkStockSelected.size)return toast('Seleziona almeno un prodotto.');
    const label=op.value==='reset'?'azzerare a 0':(op.value==='load'?'caricare':'scaricare');
    const whName=warehouseById(warehouse.value)?.name||warehouse.value;
    if(!await confirmDialog(`Vuoi ${label} ${bulkStockSelected.size} prodotti nel magazzino “${whName}”?`,'Conferma gestione massiva'))return;
    try{
      const qtyInput=$('#bulkStockQty');
      const qty=op.value==='reset'?1:Math.max(1,Number(qtyInput?.value)||1);
      await bulkUpdateStock([...bulkStockSelected],warehouse.value,op.value,qty,`Gestione massiva: ${label}`);
      bulkStockSelected.clear();
      toast('Operazione massiva completata.');
      renderBulkStockManager();
    }catch(err){toast(err.message||'Errore gestione massiva.')}
  };
}


export function renderDiscounts(){const arr=(state.discounts||[]).slice(0,pageSize('#discountPageSize'));$('#discountList').innerHTML=arr.map(d=>`<div class="discount-list-row"><div class="discount-code-mark">${esc(String(d.code||d.id||'').slice(0,3))}</div><div><b>${esc(d.code||d.id||'')}</b><small>${d.type==='fixed'?money(d.value):Number(d.value||0)+'%'} · ${d.cumulative===false?'Non cumulabile':'Cumulabile'}${d.note?' · '+esc(d.note):''}</small></div><div class="discount-status"><span class="pill ${d.active===false?'badge-danger':'badge-ok'}">${d.active===false?'Disattivo':'Attivo'}</span><span class="pill">${d.cumulative===false?'NO cumulabile':'Cumulabile'}</span></div><div class="actions"><button class="btn secondary compact-btn" data-edit-discount="${esc(d.id||d.code)}">Modifica</button><button class="btn danger compact-btn" data-delete-discount="${esc(d.id||d.code)}">Elimina</button></div></div>`).join('')||'<div class="empty">Nessun codice sconto.</div>';document.querySelectorAll('[data-edit-discount]').forEach(b=>b.onclick=()=>openDiscount(state.discounts.find(x=>String(x.id||x.code)===b.dataset.editDiscount)));document.querySelectorAll('[data-delete-discount]').forEach(b=>b.onclick=async()=>{if(!await confirmDialog('Eliminare questo codice sconto?','Elimina codice sconto'))return;try{await deleteDiscount(b.dataset.deleteDiscount);toast('Codice eliminato.')}catch(e){toast(e.message||'Errore eliminazione.')}})}
export function addDiscount(){openDiscount(null)}
function openDiscount(d){if(!can('manageDiscounts')&&!can('settings'))return toast('Permesso insufficiente.');openModal(d?'Modifica codice sconto':'Nuovo codice sconto',`<form id="discountForm" class="form-grid"><label>Codice<input id="dfCode" required value="${esc(d?.code||d?.id||'')}" ${d?'readonly':''}></label><label>Tipo<select id="dfType"><option value="percent" ${d?.type!=='fixed'?'selected':''}>Percentuale</option><option value="fixed" ${d?.type==='fixed'?'selected':''}>Importo fisso</option></select></label><label>Valore<input id="dfValue" type="number" step="0.01" min="0" required value="${Number(d?.value||0)}"></label><label>Attivo<select id="dfActive"><option value="1" ${d?.active!==false?'selected':''}>Sì</option><option value="0" ${d?.active===false?'selected':''}>No</option></select></label><label class="full">Cumulabilità<select id="dfCumulative"><option value="1" ${d?.cumulative!==false?'selected':''}>Cumulabile — vale anche sui prodotti già scontati</option><option value="0" ${d?.cumulative===false?'selected':''}>Non cumulabile — esclude i prodotti già scontati</option></select></label><label class="full">Nota<input id="dfNote" value="${esc(d?.note||'')}"></label><div class="full"><button class="btn primary">Salva</button></div></form>`);$('#discountForm').onsubmit=async e=>{e.preventDefault();try{await saveDiscount({code:$('#dfCode').value.trim(),type:$('#dfType').value,value:Number($('#dfValue').value),active:$('#dfActive').value==='1',cumulative:$('#dfCumulative').value==='1',note:$('#dfNote').value.trim()});closeModal();toast('Codice salvato.')}catch(err){toast(err.message||'Errore salvataggio.')}}}

export function loadEmployees(){renderEmployees()}
function bindRoleLegendAction(){const b=$('#manageRolesBtn');if(b)b.onclick=()=>go('roles')}
function roleLegend(){const summaries={seller:'Vendite, catalogo, magazzino, storico, sconti in consultazione, chiusure e dati economici.',supervisor:'Tutto il Venditore + annullamenti/resi, modifica pagamenti e gestione chiusure.',admin:'Gestione completa del negozio: prodotti, sconti, dipendenti, accessi e impostazioni.',owner:'Accesso totale e amministrazione completa. Ruolo protetto.'};return `<div class="role-legend-card"><div class="role-legend-head"><div><b>Legenda ruoli</b><small>I permessi indicati sono i predefiniti del ruolo. Puoi personalizzarli dalla Gestione ruoli oppure per singolo dipendente.</small></div><button type="button" id="manageRolesBtn" class="btn secondary compact-btn">Gestione ruoli</button></div><div class="role-legend-grid">${[['seller','Venditore'],['supervisor','Supervisore'],['admin','Admin'],['owner','Owner']].map(([key,label])=>`<div><strong>${label}</strong><span>${summaries[key]}</span></div>`).join('')}</div></div>`}
let employeeOverviewId='';
export function openEmployeeOverview(id){employeeOverviewId=String(id||'');go('employee-overview');renderEmployeeOverview()}
function renderEmployees(){const list=(state.employees||[]).slice(0,pageSize('#employeePageSize'));const legend=$('#roleLegend');if(legend){legend.innerHTML=roleLegend();bindRoleLegendAction()}$('#employeesList').innerHTML=list.map(u=>`<div class="employee-row"><div><b>${esc(u.name||u.email||'Utente')}</b><small>${esc(u.email||'')} · ${esc(u.role||'seller')}</small></div><div class="actions"><span class="pill ${u.active===false?'badge-danger':'badge-ok'}">${u.active===false?'Disattivo':'Attivo'}</span><button class="btn secondary compact-btn" data-overview-employee="${esc(u.id)}">Panoramica</button><button class="btn secondary compact-btn" data-edit-employee="${esc(u.id)}">Modifica</button><button class="btn danger compact-btn" data-delete-employee="${esc(u.id)}">Elimina</button></div></div>`).join('')||'<div class="empty">Nessun dipendente.</div>';document.querySelectorAll('[data-overview-employee]').forEach(b=>b.onclick=()=>openEmployeeOverview(b.dataset.overviewEmployee));document.querySelectorAll('[data-edit-employee]').forEach(b=>b.onclick=()=>editEmployee(list.find(x=>String(x.id)===b.dataset.editEmployee)));document.querySelectorAll('[data-delete-employee]').forEach(b=>b.onclick=async()=>{const u=state.employees.find(x=>String(x.id)===b.dataset.deleteEmployee);if(!u)return;if(!await confirmDialog(`Eliminare il profilo di ${u.name||u.email||'questo dipendente'}? L’account non potrà più accedere al gestionale.`,'Elimina dipendente'))return;try{await deleteEmployeeProfile(u.id);toast('Dipendente eliminato.')}catch(e){toast(e.message||'Errore eliminazione dipendente.')}})}
export function renderEmployeeOverview(){
  const box=$('#employeeOverviewContent');if(!box)return;const u=state.employees.find(x=>String(x.id)===String(employeeOverviewId));if(!u){box.innerHTML='<div class="empty">Dipendente non disponibile.</div>';return}
  const matchOrder=o=>String(o.sellerUid||o.employeeUid||'')===String(u.id)||String(o.sellerEmail||o.employeeEmail||'').toLowerCase()===String(u.email||'').toLowerCase()||String(o.sellerName||o.employeeName||'').toLowerCase()===String(u.name||'').toLowerCase();
  const orders=activeOrders().filter(matchOrder);const revenue=orders.reduce((a,o)=>a+Number(o.total||0),0);const qty=orders.reduce((a,o)=>a+(o.items||[]).reduce((b,i)=>b+Number(i.qty||0),0),0);const avg=orders.length?revenue/orders.length:0;const team=activeOrders();const teamAvg=team.length?team.reduce((a,o)=>a+Number(o.total||0),0)/team.length:0;
  const items=orders.flatMap(o=>(o.items||[]).map(i=>({...i,order:o})));const byName=new Map(),byBrand=new Map(),byCat=new Map();for(const i of items){const q=Number(i.qty||0),n=i.productName||'Prodotto',p=state.products.find(x=>String(x.id)===String(i.productId));byName.set(n,(byName.get(n)||0)+q);const br=p?.brand||i.brand||'';if(br)byBrand.set(br,(byBrand.get(br)||0)+q);const c=p?.category||i.category||'';if(c)byCat.set(c,(byCat.get(c)||0)+q)}const top=(m,n=3)=>[...m.entries()].sort((a,b)=>b[1]-a[1]).slice(0,n);
  const now=new Date(),days=[];for(let k=6;k>=0;k--){const d=new Date(now);d.setDate(now.getDate()-k);const key=d.toISOString().slice(0,10);const value=orders.filter(o=>{const od=toDate(o.date||o.createdAtClient||o.createdAt);return od&&od.toISOString().slice(0,10)===key}).reduce((a,o)=>a+Number(o.total||0),0);days.push({label:d.toLocaleDateString('it-IT',{weekday:'short'}),value})}const max=Math.max(1,...days.map(d=>d.value));
  const suggestions=[];if(avg<teamAvg&&orders.length>2)suggestions.push(`Il ticket medio (${money(avg)}) è sotto la media complessiva (${money(teamAvg)}): prova a proporre un secondo articolo complementare prima di chiudere la vendita.`);if(qty/Math.max(1,orders.length)<1.4)suggestions.push('Le vendite hanno pochi articoli per ordine: può essere utile lavorare sul cross-sell e sulle combinazioni di formato/prodotto.');const topCat=top(byCat,1)[0]?.[0],topBrand=top(byBrand,1)[0]?.[0];if(topCat)suggestions.push(`La categoria più venduta è “${topCat}”: mantienila come punto di forza e abbinala a prodotti affini disponibili.`);if(topBrand)suggestions.push(`Il brand con più pezzi venduti è “${topBrand}”: può essere usato come aggancio per proporre alternative dello stesso marchio.`);if(!suggestions.length)suggestions.push('Storico ancora limitato: raccogli più vendite per ottenere suggerimenti più precisi.');
  const candidates=state.products.filter(p=>p.deleted!==true&&productQty(p)>0&&((topCat&&p.category===topCat)||(topBrand&&p.brand===topBrand))).sort((a,b)=>productQty(b)-productQty(a)).slice(0,4);
  box.innerHTML=`<div class="detail-page-head"><button class="btn secondary compact-btn" id="backEmployees">← Dipendenti</button><div class="detail-page-title"><span>Panoramica dipendente</span><h2>${esc(u.name||u.email||'Dipendente')}</h2></div></div><div class="employee-overview-grid"><section class="panel employee-overview-identity"><div class="employee-avatar-lg">${u.avatar?`<img src="${esc(u.avatar)}" alt="">`:esc(String(u.name||u.email||'D').charAt(0).toUpperCase())}</div><h2>${esc(u.name||'—')}</h2><p>${esc(u.email||'')} · ${esc(u.role||'seller')}</p><span class="pill ${u.active===false?'badge-danger':'badge-ok'}">${u.active===false?'Disattivo':'Attivo'}</span><div class="employee-mini-stats"><div><span>Ordini</span><b>${orders.length}</b></div><div><span>Incasso</span><b>${money(revenue)}</b></div><div><span>Articoli</span><b>${qty}</b></div><div><span>Ticket medio</span><b>${money(avg)}</b></div></div></section><section class="panel employee-overview-main"><div class="panel-head"><div><h2>Andamento 7 giorni</h2><p>Incasso generato dal dipendente.</p></div></div><div class="employee-bar-chart">${days.map(d=>`<div><span>${money(d.value)}</span><i><b style="height:${Math.max(4,Math.round(d.value/max*100))}%"></b></i><small>${esc(d.label)}</small></div>`).join('')}</div><div class="overview-split"><div><h3>Più venduti</h3>${top(byName).map(([n,v])=>`<div class="rank-row"><span>${esc(n)}</span><b>${v} pz</b></div>`).join('')||'<div class="empty compact">Nessun dato.</div>'}</div><div><h3>Punti di miglioramento</h3>${suggestions.map(s=>`<div class="insight-row">${esc(s)}</div>`).join('')}</div></div><div class="panel-head"><div><h2>Cosa proporre ai clienti</h2><p>Suggerimenti ricavati dalle categorie/brand che questo dipendente vende meglio e dalla disponibilità attuale.</p></div></div><div class="employee-product-suggestions">${candidates.map(p=>`<button type="button" data-emp-product="${esc(p.id)}">${thumb(p,'mini-thumb')}<span><b>${esc(p.name||'Prodotto')}</b><small>${esc(p.brand||'')} · ${productQty(p)} pz</small></span></button>`).join('')||'<div class="empty">Nessun prodotto suggerito con i dati attuali.</div>'}</div></section></div><section class="panel employee-access-panel"><div class="panel-head"><div><h2>I suoi accessi</h2><p>Spunta ciò che questo dipendente può fare. Le modifiche valgono solo per questo account e prevalgono sul ruolo.</p></div><button type="button" class="btn secondary compact-btn" id="resetEmployeePermissions">Usa permessi del ruolo</button></div><div class="permission-grid">${permissionCatalog.map(item=>{const inherited=permissionsForRole(u.role)[item.key];const overrides=u.permissionOverrides||{};const checked=Object.prototype.hasOwnProperty.call(overrides,item.key)?!!overrides[item.key]:!!inherited;return `<label class="permission-card"><input type="checkbox" name="employeePermission" value="${esc(item.key)}" ${checked?'checked':''}><span><b>${esc(item.label)}</b><small>${esc(item.desc)}</small></span></label>`}).join('')}</div><div class="permission-actions"><small>Ruolo attuale: <b>${esc(u.role||'seller')}</b></small><button type="button" class="btn primary" id="saveEmployeePermissions">Salva accessi dipendente</button></div></section>`;$('#backEmployees').onclick=()=>go('employees');document.querySelectorAll('[data-emp-product]').forEach(b=>b.onclick=()=>openProduct(state.products.find(p=>String(p.id)===b.dataset.empProduct)));
  const applyRoleChecks=()=>{const base=permissionsForRole(u.role);document.querySelectorAll('input[name="employeePermission"]').forEach(x=>x.checked=!!base[x.value])};
  const resetBtn=$('#resetEmployeePermissions');if(resetBtn)resetBtn.onclick=applyRoleChecks;
  const saveBtn=$('#saveEmployeePermissions');if(saveBtn)saveBtn.onclick=async()=>{const overrides={};document.querySelectorAll('input[name="employeePermission"]').forEach(x=>overrides[x.value]=!!x.checked);try{await updateEmployeeProfile(u.id,{permissionOverrides:overrides});u.permissionOverrides=overrides;toast('Accessi del dipendente aggiornati.')}catch(e){toast(e.message||'Errore salvataggio accessi.')}};
}

function editEmployee(u){if(!u)return;openModal('Modifica dipendente',`<form id="employeeEditForm" class="form-grid"><label>Nome<input id="eeName" value="${esc(u.name||'')}"></label><label>Email profilo<input id="eeEmail" type="email" value="${esc(u.email||'')}"></label><label>Ruolo<select id="eeRole"><option value="seller" ${u.role==='seller'?'selected':''}>Venditore</option><option value="supervisor" ${u.role==='supervisor'?'selected':''}>Supervisore</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option><option value="owner" ${u.role==='owner'?'selected':''}>Owner</option></select></label><label>Stato<select id="eeActive"><option value="1" ${u.active!==false?'selected':''}>Attivo</option><option value="0" ${u.active===false?'selected':''}>Disattivo</option></select></label><label>Punto vendita assegnato<input id="eePosSearch" type="search" autocomplete="off" placeholder="Cerca sede per nome o codice"><select id="eePointOfSale"><option value="">— Non assegnato —</option>${(state.settings.pointsOfSale||[]).filter(x=>x.active!==false&&x.deleted!==true).map(x=>`<option value="${esc(x.id)}" ${String(u.pointOfSaleId||'')===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="check-setting"><input type="checkbox" id="eeSellOnline" ${u.sellOnline===true?'checked':''}> Permesso richiesto: vendita da NOOR ONLINE (non attivo fino a rilascio sicurezza)</label><label>Magazzino predefinito<select id="eeWarehouse">${warehouses().map(w=>`<option value="${esc(w.id)}" ${String(u.preferredWarehouseId||'')===String(w.id)?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><div class="full"><span class="field-label">Magazzini visibili</span><div class="warehouse-permission-grid">${warehouses().map(w=>`<label><input type="checkbox" name="eeAllowedWarehouse" value="${esc(w.id)}" ${!Array.isArray(u.allowedWarehouseIds)||u.allowedWarehouseIds.includes(w.id)?'checked':''}> ${esc(w.name)}</label>`).join('')}</div></div><div class="full employee-role-note">La modifica dell'email aggiorna il profilo Firestore. L'email di autenticazione Firebase va cambiata lato account se necessario.</div><div class="full"><button class="btn primary">Salva modifiche</button></div></form>`);bindPointOfSaleSearch('#eePosSearch','#eePointOfSale');$('#employeeEditForm').onsubmit=async e=>{e.preventDefault();try{await updateEmployeeProfile(u.id,{name:$('#eeName').value.trim(),email:$('#eeEmail').value.trim(),role:$('#eeRole').value,active:$('#eeActive').value==='1',pointOfSaleId:$('#eePointOfSale').value,sellOnline:$('#eeSellOnline').checked,preferredWarehouseId:$('#eeWarehouse').value,allowedWarehouseIds:Array.from(document.querySelectorAll('input[name="eeAllowedWarehouse"]:checked')).map(x=>x.value)});closeModal();toast('Dipendente aggiornato.')}catch(err){toast(err.message||'Errore aggiornamento dipendente.')}}}

export function addEmployee(){openModal('Nuovo dipendente',`<form id="empForm" class="form-grid"><label>Nome<input id="efName" required></label><label>Email<input id="efEmail" type="email" required></label><label>Password temporanea<input id="efPassword" type="password" minlength="8" required></label><label>Ruolo<select id="efRole"><option value="seller">Venditore</option><option value="supervisor">Supervisore</option><option value="admin">Admin</option></select></label><label>Punto vendita assegnato<input id="efPosSearch" type="search" autocomplete="off" placeholder="Cerca sede per nome o codice"><select id="efPointOfSale"><option value="">— Non assegnato —</option>${(state.settings.pointsOfSale||[]).filter(x=>x.active!==false&&x.deleted!==true).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><label>Magazzino predefinito<select id="efWarehouse">${warehouses().map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('')}</select></label><div class="full"><span class="field-label">Magazzini visibili</span><div class="warehouse-permission-grid">${warehouses().map(w=>`<label><input type="checkbox" name="efAllowedWarehouse" value="${esc(w.id)}" checked> ${esc(w.name)}</label>`).join('')}</div></div><div class="full"><button class="btn primary">Crea account</button></div></form><p class="muted">In locale la creazione richiede Netlify Dev o il deploy perché usa la Function amministrativa.</p>`);bindPointOfSaleSearch('#efPosSearch','#efPointOfSale');$('#empForm').onsubmit=async e=>{e.preventDefault();try{const {auth}=await import('./firebase.js');const token=await auth.currentUser.getIdToken(true);const res=await fetch('/.netlify/functions/createEmployee',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({action:'create',name:$('#efName').value.trim(),email:$('#efEmail').value.trim(),password:$('#efPassword').value,role:$('#efRole').value,active:true,pointOfSaleId:$('#efPointOfSale').value,preferredWarehouseId:$('#efWarehouse').value,allowedWarehouseIds:Array.from(document.querySelectorAll('input[name="efAllowedWarehouse"]:checked')).map(x=>x.value)})});const data=await res.json();if(!res.ok||!data.ok)throw new Error(data.error||'Errore creazione');if(data.uid)await updateEmployeeProfile(data.uid,{pointOfSaleId:$('#efPointOfSale').value,preferredWarehouseId:$('#efWarehouse').value,allowedWarehouseIds:Array.from(document.querySelectorAll('input[name="efAllowedWarehouse"]:checked')).map(x=>x.value)});closeModal();toast('Dipendente creato.')}catch(e){toast(e.message||'Funzione non disponibile in locale.')}}}

export function renderShifts(){
  const all=(state.shifts||[]).filter(x=>inManagementPeriod(x,state.settings)),deleted=all.filter(s=>s.deleted===true),visible=all.filter(s=>s.deleted!==true&&((s.sellerUid===state.profile?.uid||s.employeeUid===state.profile?.uid)||can('manageEmployees')||can('settings')));
  const from=$('#shiftHoursFrom')?.value||'',to=$('#shiftHoursTo')?.value||'',employee=$('#shiftHoursEmployee')?.value||'all',month=$('#shiftHoursMonth')?.value||'all',year=$('#shiftHoursYear')?.value||'all';
  const filtered=visible.filter(s=>{const d=toDate(s.startAtClient||s.startAt);if(!d)return false;const day=d.toISOString().slice(0,10);const monthOk=month==='all'||String(d.getMonth()+1).padStart(2,'0')===month;const yearOk=year==='all'||String(d.getFullYear())===year;return (!from||day>=from)&&(!to||day<=to)&&(employee==='all'||String(s.sellerUid||s.employeeUid||'')===employee)&&monthOk&&yearOk});
  const closed=filtered.filter(s=>s.status!=='open'&&(s.endAtClient||s.endAt));const mins=closed.reduce((a,s)=>{const st=toDate(s.startAtClient||s.startAt),en=toDate(s.endAtClient||s.endAt);return a+(st&&en?Math.max(0,(en-st)/60000):0)},0);const h=Math.floor(mins/60),m=Math.round(mins%60);
  const peopleMap=new Map();for(const u of (state.employees||[])){if(u.active===false)continue;const id=String(u.id||u.uid||'');if(id)peopleMap.set(id,{id,name:u.name||u.email||'Dipendente'});}for(const s of visible){const id=String(s.sellerUid||s.employeeUid||'');if(id&&!peopleMap.has(id))peopleMap.set(id,{id,name:s.sellerName||s.employeeName||'Dipendente'});}const people=[...peopleMap.values()].sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'it'));const years=Array.from(new Set(visible.map(s=>toDate(s.startAtClient||s.startAt)?.getFullYear()).filter(Boolean))).sort((a,b)=>b-a);const months=[['01','Gennaio'],['02','Febbraio'],['03','Marzo'],['04','Aprile'],['05','Maggio'],['06','Giugno'],['07','Luglio'],['08','Agosto'],['09','Settembre'],['10','Ottobre'],['11','Novembre'],['12','Dicembre']];
  const open=visible.find(s=>s.status==='open'&&!s.endAtClient);
  const shiftIntervals=filtered.map(s=>({uid:String(s.sellerUid||s.employeeUid||''),start:toDate(s.startAtClient||s.startAt),end:s.status==='open'&&!s.endAtClient?new Date():toDate(s.endAtClient||s.endAt)})).filter(x=>x.start&&x.end);
  const shiftOrders=activeOrders().filter(o=>{const od=toDate(o.date||o.createdAtClient||o.createdAt);const uid=String(o.sellerUid||o.employeeUid||'');return od&&shiftIntervals.some(x=>(!x.uid||x.uid===uid)&&od>=x.start&&od<=x.end)});
  const shiftRevenue=shiftOrders.reduce((a,o)=>a+Number(o.total||0),0);
  $('#shiftsContent').innerHTML=`<div class="shift-top-actions"><button id="toggleDeletedShifts" class="btn secondary">Turni eliminati <span class="count-dot">${deleted.length}</span></button></div><div id="deletedShiftsPanel" class="deleted-shifts-panel hidden"><div class="section-subhead"><h3>Turni eliminati</h3><span>${deleted.length}</span></div><div class="list">${deleted.map(s=>`<div class="list-row"><div><b>${esc(s.sellerName||s.employeeName||'Turno')}</b><small>${fmtDate(s.startAtClient||s.startAt)}</small></div><div class="actions"><button class="btn primary compact-btn" data-restore-shift="${esc(s.id)}">Ripristina</button>${['owner','superadmin','super-admin','super_admin'].includes(String(state.profile?.role||'').toLowerCase())?`<button class="btn danger compact-btn" data-permanent-delete-shift="${esc(s.id)}">Elimina definitivamente</button>`:''}</div></div>`).join('')||'<div class="empty">Nessun turno eliminato.</div>'}</div></div><div class="shift-current-card"><div><span>Turno corrente</span><b>${open?'Aperto':'Nessun turno aperto'}</b><small>${open?'Inizio '+fmtDate(open.startAtClient||open.startAt):'Apri un turno per collegare le vendite alla sessione.'}</small></div>${open?'<button id="shiftAction" class="btn danger">Termina turno</button>':'<button id="shiftAction" class="btn primary">Inizia turno</button>'}</div><div class="shift-hours-card"><div class="section-subhead"><h3>Riepilogo turni</h3></div><div class="shift-summary-kpis"><div><span>Ore lavorate</span><b>${h}h ${String(m).padStart(2,'0')}m</b></div><div><span>Ordini</span><b>${shiftOrders.length}</b></div><div><span>Incasso</span><b>${money(shiftRevenue)}</b></div></div><div class="shift-hours-filters shift-hours-filters-extended"><label>Da<input id="shiftHoursFrom" type="date" value="${esc(from)}"></label><label>A<input id="shiftHoursTo" type="date" value="${esc(to)}"></label><label>Mese<select id="shiftHoursMonth"><option value="all">Tutti i mesi</option>${months.map(m=>`<option value="${m[0]}" ${month===m[0]?'selected':''}>${m[1]}</option>`).join('')}</select></label><label>Anno<select id="shiftHoursYear"><option value="all">Tutti gli anni</option>${years.map(y=>`<option value="${y}" ${String(year)===String(y)?'selected':''}>${y}</option>`).join('')}</select></label><label>Dipendente<select id="shiftHoursEmployee"><option value="all">Tutti</option>${people.map(p=>`<option value="${esc(p.id)}" ${employee===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="shift-filter-actions"><button type="button" id="resetShiftFilters" class="btn secondary">Azzera filtri</button></div></div><small>${closed.length} turni chiusi nel periodo</small></div><div class="section-subhead"><h3>Storico turni</h3><span>${filtered.length}</span></div><div class="list">${filtered.slice(0,pageSize('#shiftPageSize')).map(s=>`<div class="list-row"><div><b>${esc(s.sellerName||s.employeeName||'Turno')}</b><small>${fmtDate(s.startAtClient||s.startAt)} → ${s.status==='open'?'in corso':fmtDate(s.endAtClient||s.endAt)}</small></div><div class="actions"><span class="pill">${esc(s.status||'—')}</span>${can('settings')?`<button class="btn secondary compact-btn" data-edit-shift="${esc(s.id)}">Modifica</button><button class="btn danger compact-btn" data-delete-shift="${esc(s.id)}">Elimina</button>`:''}</div></div>`).join('')||'<div class="empty">Nessun turno.</div>'}</div>`;
  $('#shiftAction').onclick=async()=>{try{if(open)await closeShift(open);else await startShift();toast(open?'Turno terminato.':'Turno iniziato.')}catch(e){toast(e.message||'Errore turno.')}};
  $('#toggleDeletedShifts').onclick=()=>$('#deletedShiftsPanel').classList.toggle('hidden');['#shiftHoursFrom','#shiftHoursTo','#shiftHoursMonth','#shiftHoursYear','#shiftHoursEmployee'].forEach(id=>{if($(id))$(id).onchange=renderShifts});const resetShiftFilters=$('#resetShiftFilters');if(resetShiftFilters)resetShiftFilters.onclick=()=>{['#shiftHoursFrom','#shiftHoursTo'].forEach(id=>{if($(id))$(id).value=''});['#shiftHoursMonth','#shiftHoursYear','#shiftHoursEmployee'].forEach(id=>{if($(id))$(id).value='all'});renderShifts()};
  document.querySelectorAll('[data-edit-shift]').forEach(b=>b.onclick=()=>editShift(all.find(x=>x.id===b.dataset.editShift)));document.querySelectorAll('[data-delete-shift]').forEach(b=>b.onclick=async()=>{if(await confirmDialog('Spostare questo turno tra gli eliminati?','Elimina turno'))await deleteShift(b.dataset.deleteShift)});document.querySelectorAll('[data-restore-shift]').forEach(b=>b.onclick=()=>restoreShift(b.dataset.restoreShift));
  document.querySelectorAll('[data-permanent-delete-shift]').forEach(b=>b.onclick=async()=>{
    const id=b.dataset.permanentDeleteShift;
    if(!await confirmDialog('Eliminare definitivamente questo turno archiviato? Solo i turni chiusi senza vendite e chiusure collegate possono essere rimossi. Questa operazione non modifica le giacenze.','Elimina definitivamente turno'))return;
    if(!await confirmDialog('Conferma finale: il turno verrà cancellato dal database e non potrà essere recuperato.','Conferma cancellazione definitiva'))return;
    b.disabled=true;
    try{await permanentlyDeleteArchivedShift(id);toast('Turno eliminato definitivamente. Nessuna giacenza modificata.');renderShifts()}catch(e){toast(e?.message||'Eliminazione del turno non riuscita.')}finally{b.disabled=false}
  })
}
function editShift(s){openModal('Modifica turno',`<form id="shiftEditForm" class="form-grid"><label>Nome dipendente<input id="seName" value="${esc(s.sellerName||s.employeeName||'')}"></label><label>Stato<select id="seStatus"><option value="open" ${s.status==='open'?'selected':''}>Aperto</option><option value="closed" ${s.status!=='open'?'selected':''}>Chiuso</option></select></label><label>Inizio<input id="seStart" type="datetime-local" value="${String(s.startAtClient||'').slice(0,16)}"></label><label>Fine<input id="seEnd" type="datetime-local" value="${String(s.endAtClient||'').slice(0,16)}"></label><div class="full"><button class="btn primary">Salva</button></div></form>`);$('#shiftEditForm').onsubmit=async e=>{e.preventDefault();await updateShift(s.id,{sellerName:$('#seName').value.trim(),employeeName:$('#seName').value.trim(),status:$('#seStatus').value,startAtClient:$('#seStart').value?new Date($('#seStart').value).toISOString():s.startAtClient,endAtClient:$('#seEnd').value?new Date($('#seEnd').value).toISOString():''});closeModal();toast('Turno aggiornato.')}}
let homeShiftTimer=null;
export function renderHomeShift(){
  const box=$('#shiftHome');if(!box)return;const shiftSource=state.loaded.shifts?(state.shifts||[]):((state.fastHomeCache?.ready?.shifts?(state.fastHomeCache.shifts||[]):[]));const shifts=shiftSource.filter(s=>inManagementPeriod(s,state.settings)&&s.deleted!==true&&(s.sellerUid===state.profile?.uid||s.employeeUid===state.profile?.uid));const open=shifts.find(s=>s.status==='open'&&!s.endAtClient);if(homeShiftTimer){clearInterval(homeShiftTimer);homeShiftTimer=null}
  if(!open){box.innerHTML=`<div class="home-shift-empty"><div class="shift-ring idle"><span>00:00</span></div><div><small>Turno dipendente</small><b>Nessun turno aperto</b><p>Avvia il turno per monitorare tempo e incasso.</p></div><button id="homeShiftBtn" class="btn primary">Inizia turno</button></div>`;$('#homeShiftBtn').onclick=async()=>{await startShift();toast('Turno iniziato.')};return}
  const start=toDate(open.startAtClient||open.startAt)||new Date();const update=()=>{const elapsed=Math.max(0,Date.now()-start.getTime()),mins=Math.floor(elapsed/60000),hh=Math.floor(mins/60),mm=mins%60,pct=Math.min(100,(elapsed/(8*3600000))*100);const ring=box.querySelector('.shift-ring');if(ring){ring.style.setProperty('--progress',pct+'%');ring.querySelector('span').textContent=String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0')}const orderSource=state.loaded.orders?activeOrders():((state.fastHomeCache?.ready?.orders?(state.fastHomeCache.orders||[]):[]).filter(o=>!(String(o.status||'').toLowerCase().includes('cancel')||o.cancelled===true)));const orders=orderSource.filter(o=>String(o.sellerUid||o.employeeUid||'')===String(state.profile?.uid||'')&&((toDate(o.date||o.createdAtClient||o.createdAt)||new Date(0))>=start));const revenue=orders.reduce((a,o)=>a+Number(o.total||0),0);const rev=box.querySelector('[data-shift-revenue]');if(rev)rev.textContent=money(revenue);const oc=box.querySelector('[data-shift-orders]');if(oc)oc.textContent=orders.length};
  box.innerHTML=`<div class="home-shift-live"><div class="shift-ring"><span>00:00</span></div><div class="home-shift-copy"><small>Turno dipendente</small><b>${esc(open.sellerName||open.employeeName||state.profile?.name||'')}</b><p>Inizio ${fmtDate(open.startAtClient||open.startAt)}</p></div><div class="shift-live-kpis"><div><span>Incasso turno</span><b data-shift-revenue>—</b></div><div><span>Ordini</span><b data-shift-orders>0</b></div></div><button id="homeShiftBtn" class="btn danger compact-btn">Termina</button></div>`;update();homeShiftTimer=setInterval(update,60000);$('#homeShiftBtn').onclick=async()=>{await closeShift(open);toast('Turno terminato.')}
}

