// Gestione sedi: lista persistente + scheda nuova separata dalle sedi salvate.
// Sedi: archiviazione reversibile e cancellazione definitiva soltanto senza riferimenti.
function pointOfSaleReferences(id){
 const key=String(id||'');
 const employees=(state.employees||[]).some(u=>String(u.pointOfSaleId||'')===key);
 const history=[...(state.orders||[]),...(state.shifts||[]),...(state.closures||[]),...(state.cancelledOrders||[])];
 const historic=history.some(x=>String(x.pointOfSaleId||x.storeId||'')===key);
 return {employees,historic};
}
async function archivePointOfSale(i){
 if(!can('settings'))return toast('Permesso non sufficiente.');
 const list=state.settings.pointsOfSale||[],p=list[i];if(!p||p.deleted===true)return;
 const refs=pointOfSaleReferences(p.id);
 if(refs.employees)return toast('Prima riassegna i dipendenti di questa sede.');
 if(!await confirmDialog(`Archiviare la sede ${p.name} (${p.id})? Incassi e chiusure storiche resteranno conservati.`, 'Elimina punto vendita'))return;
 try{await saveSettings({pointsOfSale:list.map((x,j)=>i===j?{...x,active:false,deleted:true,deletedAtClient:new Date().toISOString()}:x)});renderPointsOfSale();toast('Sede spostata tra i punti vendita eliminati.')}catch(err){toast(err.message||'Archiviazione non riuscita.')}
}
async function restorePointOfSale(i){
 if(!can('settings'))return toast('Permesso non sufficiente.');
 const list=state.settings.pointsOfSale||[],p=list[i];if(!p||p.deleted!==true)return;
 if(!await confirmDialog(`Recuperare ${p.name} (${p.id})?`, 'Recupera sede'))return;
 try{await saveSettings({pointsOfSale:list.map((x,j)=>i===j?{...x,active:true,deleted:false,deletedAtClient:''}:x)});renderPointsOfSale();toast('Sede recuperata.')}catch(err){toast(err.message||'Recupero non riuscito.')}
}
async function purgePointOfSale(i){
 if(!can('settings'))return toast('Permesso non sufficiente.');
 const list=state.settings.pointsOfSale||[],p=list[i];if(!p||p.deleted!==true)return;
 const refs=pointOfSaleReferences(p.id);
 if(refs.employees||refs.historic)return toast('Eliminazione definitiva bloccata: sede collegata a dipendenti, vendite, turni o chiusure. Può restare archiviata.');
 if(!await confirmDialog(`Eliminare DEFINITIVAMENTE ${p.name} (${p.id})?`, 'Eliminazione definitiva'))return;
 if(!await confirmDialog('Ultima conferma: la scheda della sede non sarà recuperabile.', 'Conferma definitiva'))return;
 try{await saveSettings({pointsOfSale:list.filter((_,j)=>j!==i)});renderPointsOfSale();toast('Punto vendita eliminato definitivamente.')}catch(err){toast(err.message||'Eliminazione non riuscita.')}
}
