let posMigrationState=null;
function bindPosMigration(){
 const root=$('#posMigrationPanel');if(!root||!isMigrationAdmin(state.profile))return;
 root.innerHTML='<div class="panel" style="padding:18px;margin-top:16px"><h3>Migrazione storici — NR-002</h3><p class="muted">Scansione completa Firebase (non i soli dati caricati nel browser). Anteprima senza scritture. Vendite, turni e chiusure senza sede potranno essere associati a LATINFIEXPO – RESCALDINA (NR-002). Utenti esclusi dalla migrazione.</p><button class="btn secondary" id="posMigrationScan">Analizza tutti gli archivi</button><div id="posMigrationResults" style="margin-top:12px"></div></div>';
 const output=$('#posMigrationResults'),btn=$('#posMigrationScan');btn.onclick=async()=>{
  btn.disabled=true;output.textContent='Lettura archivi in corso…';
  try{
   const records=await readAllPointOfSaleCollections((name,n)=>{output.textContent='Lettura '+name+': '+n+' documenti…'});
   const target=(state.settings.pointsOfSale||[]).find(p=>p.id==='NR-002'&&p.deleted!==true);
   if(!target)throw new Error('La sede NR-002 non è disponibile.');
   const preview=migrationPreview(records,'NR-002');
   // Fail closed when older module versions are cached or an invalid preview is returned.
   if(!preview||!Array.isArray(preview.legacyReview)||!Array.isArray(preview.eligible)||!preview.stats||!Number.isSafeInteger(preview.candidateTotal)){
    posMigrationState=null;
    throw new Error('Modulo migrazione non aggiornato o anteprima incompleta. Aggiorna la pagina con Ctrl+F5 e ripeti Analizza tutti gli archivi. Nessuna scrittura effettuata.');
   }
   posMigrationState=preview;
   const expected=preview.valid;
   const labels={orders:'Vendite',shifts:'Turni',closures:'Chiusure',users:'Utenti'};
   const legacyByCollection=Object.fromEntries(Object.keys(preview.stats).map(k=>[k,preview.legacyReview.filter(x=>x.collection===k)]));
   const legacyNames=[...new Set(preview.legacyReview.map(x=>x.legacyStoreId))];
   const legacyDetails=preview.legacyReview.length?'<div class="panel" style="padding:12px;margin:12px 0"><b>Riferimenti storici da verificare: '+preview.legacyReview.length+'</b><p class="muted">Questi record non hanno pointOfSaleId ma contengono un diverso storeId. Valori rilevati: '+legacyNames.map(esc).join(', ')+'. Il vecchio campo sarà conservato.</p><label class="check-setting"><input type="checkbox" id="posMigrationLegacyApprove"> Confermo di aver verificato anche questi riferimenti e che appartengono tutti a LATINFIEXPO – RESCALDINA (NR-002)</label></div>':'';
   output.innerHTML='<div class="table-wrap"><table class="table"><thead><tr><th>Archivio</th><th>Letti</th><th>Già assegnati</th><th>Senza sede</th><th>Da verificare</th></tr></thead><tbody>'+Object.entries(preview.stats).map(([k,v])=>'<tr><td>'+labels[k]+'</td><td>'+v.total+'</td><td>'+v.assigned+'</td><td>'+v.without+'</td><td>'+legacyByCollection[k].length+'</td></tr>').join('')+'</tbody></table></div><p><b>Documenti candidati: '+preview.candidateTotal+'</b> (inclusi '+preview.legacyReview.length+' con storeId legacy da verificare; utenti esclusi).</p><p class="muted">'+(expected?'Conteggi coerenti con la scansione completa: 324 vendite, 37 turni e 22 chiusure.':'ATTENZIONE: conteggi non conformi oppure documenti attribuiti ad altra sede. Migrazione BLOCCATA.')+'</p>'+legacyDetails+'<p class="muted">La scansione sarà ripetuta prima della scrittura; ogni documento sarà verificato in transazione. Non sono modificati importi, prodotti, giacenze o Shopify.</p><label class="check-setting"><input type="checkbox" id="posMigrationApprove"> Confermo che tutte le vendite, i turni e le chiusure senza sede appartengono a NR-002</label><label>Scrivi NR-002 per autorizzare l’operazione<input id="posMigrationCode" autocomplete="off" placeholder="NR-002"></label><button class="btn danger" id="posMigrationApply" type="button" '+(expected?'':'disabled')+'>Applica attribuzione storica</button><p id="posMigrationProgress" class="muted"></p>';
   $('#posMigrationApply').onclick=async()=>{
    if(!expected)return toast('Conteggi non coincidenti: nessuna migrazione consentita.');
    if(!$('#posMigrationApprove').checked||$('#posMigrationCode').value.trim()!=='NR-002')return toast('Conferma la sede e digita NR-002.');
    if(preview.legacyReview.length&&!$('#posMigrationLegacyApprove')?.checked)return toast('Verifica e conferma anche i riferimenti legacy prima di procedere.');
    if(!await confirmDialog('Assegnare '+preview.candidateTotal+' vendite/turni/chiusure senza sede a LATINFIEXPO – RESCALDINA? L’operazione modifica Firebase reale.'))return;
    const apply=$('#posMigrationApply');apply.disabled=true;
    try{const done=await applyHistoricPointOfSaleMigration({preview,targetId:'NR-002',profile:state.profile,approveLegacy:preview.legacyReview.length?$('#posMigrationLegacyApprove').checked:false,onProgress:x=>{$('#posMigrationProgress').textContent='Aggiornati '+x.changed+' / '+x.total}});$('#posMigrationProgress').textContent='Migrazione completata: '+done.changed+' aggiornati, '+done.skipped+' saltati. Ripeti la scansione per verificare.';toast('Migrazione storici completata.');}
    catch(err){apply.disabled=false;$('#posMigrationProgress').textContent='Errore: '+(err.message||err);}
   };
  }catch(err){output.textContent='Scansione non riuscita: '+(err.message||err)}finally{btn.disabled=false}
 };
}
function renderNewManagementPeriod(){
 const root=$('#newManagementPeriod');if(!root)return;
 const allowed=['owner','superadmin','super-admin'].includes(String(state.profile?.role||'').toLowerCase());
 if(!allowed){root.innerHTML='';return}
 const existing=checkedPeriodStart(state.settings);
 const counts={orders:(state.orders||[]).length,shifts:(state.shifts||[]).length,closures:(state.closures||[]).length};
 root.innerHTML=`<div class="panel" style="padding:20px;margin-top:18px"><h3>Nuovo periodo gestionale — senza azzerare il magazzino</h3>
 <p class="muted">${existing?'Periodo attivo dal <b>'+esc(new Date(existing).toLocaleString('it-IT'))+'</b>.':'Nessun nuovo periodo attivato.'} Nessuna vendita o chiusura viene cancellata o annullata.</p>
 <p>Documenti attualmente caricati: ${counts.orders} vendite, ${counts.shifts} turni, ${counts.closures} chiusure. Questi numeri non rappresentano una scansione completa.</p>
 <div class="settings-info-note">I vecchi ordini restano su Firebase, senza movimenti di magazzino. Attivazione consentita solo su una versione pubblicata con regole Firebase Fase 18; non concede ancora accessi isolati ai responsabili delle sedi.</div>
 ${existing?'<p><b>Data di inizio registrata.</b> Non è previsto l’azzeramento ripetuto.</p>':`<label class="check-setting"><input type="checkbox" id="periodAcknowledge"> Ho verificato che le quantità siano corrette e che nessuna vendita precedente debba essere annullata tramite la cassa.</label><div class="actions" style="margin-top:12px"><button class="btn secondary" id="prepareManagementPeriod" type="button">Prepara inizio nuovo periodo (solo anteprima)</button></div><div id="managementPeriodPreview" class="muted"></div><div class="actions" style="margin-top:12px"><button class="btn danger" id="activateManagementPeriod" type="button">Attiva nuovo periodo (operazione reale)</button></div><label>Codice di conferma<input id="managementPeriodConfirmCode" placeholder="Scrivi ATTIVA NUOVO PERIODO" autocomplete="off"></label><div id="managementPeriodActivationResult" role="status" class="muted"></div>`}</div>`;
 const previewPanel=document.createElement('div');previewPanel.className='panel';previewPanel.style.cssText='padding:14px;margin-top:14px';
 const sites=(state.settings.pointsOfSale||[]).filter(p=>p.active!==false&&p.deleted!==true);
 previewPanel.innerHTML=`<h4>Verifica economica per sede (sola lettura)</h4><p class="muted">Simulazione del taglio di periodo alla data di oggi. I conteggi riguardano solo i documenti caricati; per la verifica completa serve la scansione Firebase.</p><label>Sede <select id="periodPreviewSite"><option value="">Seleziona punto vendita</option>${sites.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} (${esc(p.id)})</option>`).join('')}</select></label><button class="btn secondary" id="periodCheckSite" type="button">Controlla dati della sede</button><div id="periodSiteResults" role="status"></div>`;
 root.querySelector('.panel')?.append(previewPanel);
 const b=$('#prepareManagementPeriod');if(b)b.onclick=()=>{const box=$('#managementPeriodPreview');if(!$('#periodAcknowledge')?.checked){box.textContent='Prima conferma la presa visione delle giacenze.';return}box.innerHTML='<b>Anteprima:</b> nessun documento e nessuna quantità verranno modificati. La registrazione del nuovo periodo resta disabilitata finché non saranno verificate le regole Firebase e tutti i report.'};
 const activate=$('#activateManagementPeriod');if(activate)activate.onclick=async()=>{
  const out=$('#managementPeriodActivationResult');
  if(!$('#periodAcknowledge')?.checked){out.textContent='Spunta prima la verifica delle giacenze.';return}
  if(!['owner','superadmin','super-admin'].includes(String(state.profile?.role||'').toLowerCase())){out.textContent='Solo Owner o Super Admin.';return}
  if(['localhost','127.0.0.1','::1'].includes(location.hostname)){out.textContent='Attivazione bloccata in locale: questa funzione scrive su Firebase reale. Prova solo il riepilogo.';return}
  const code=$('#managementPeriodConfirmCode')?.value.trim();
  if(code!=='ATTIVA NUOVO PERIODO'){out.textContent='Scrivi esattamente ATTIVA NUOVO PERIODO per confermare.';return}
  if(!await confirmDialog('Verificare backup e regole Firebase. Il periodo parte ora, e le vendite precedenti saranno escluse dai nuovi report. Nessun prodotto verra modificato.','Attivazione nuovo periodo'))return;
  activate.disabled=true;out.textContent='Verifica e attivazione in corso...';
  try{const date=await activateManagementPeriod();out.textContent='Periodo attivato: '+new Date(date).toLocaleString('it-IT')+'. Nessuna giacenza modificata.';await loadSettings();renderNewManagementPeriod();}
  catch(err){activate.disabled=false;out.textContent='Attivazione non riuscita: '+String(err?.message||err)}
 };
 const run=$('#periodCheckSite');if(run)run.onclick=()=>{const id=$('#periodPreviewSite')?.value||'';const out=$('#periodSiteResults');if(!id){out.textContent='Seleziona una sede.';return}const r=previewPeriodBySite({orders:state.orders,shifts:state.shifts,closures:state.closures},id);
 out.innerHTML=`<div class="settings-info-note"><b>Storico caricato della sede selezionata</b><p>Vendite: <b>${r.orders}</b> · Turni: <b>${r.shifts}</b> · Chiusure: <b>${r.closures}</b> · Vendite valide (totale): <b>${money(r.salesTotal)}</b></p><p>${r.hasUnassigned?'ATTENZIONE:':'Verifica:'} record senza sede nei dati caricati: ${r.missing.orders} vendite, ${r.missing.shifts} turni, ${r.missing.closures} chiusure. ${r.hasUnassigned?'Non è possibile considerare questi dati separati in sicurezza.':'La lettura parziale non certifica la completezza degli archivi.'}</p><small>Anteprima, nessuna scrittura. La futura ripartenza non deve cancellare ordini né variare le giacenze.</small></div>`;
 };
}
export function renderPointsOfSale(){renderNewManagementPeriod();renderPointOfSaleSettings();renderPointOfSaleCoverage();bindPosMigration();const button=$('#savePointOfSale');if(button)button.classList.add('hidden');if(false&&button)button.onclick=async()=>{
 if(!can('settings'))return toast('Permesso non sufficiente.');
 button.disabled=true;
 try{const pointsOfSale=collectPointOfSaleSettings();await saveSettings({pointsOfSale});renderPointOfSaleSettings();toast('Modifiche ai punti vendita salvate.');}
 catch(e){toast(e.message||'Salvataggio non riuscito.')}finally{button.disabled=false}
};
 const add=$('#addPointOfSale');if(add)add.onclick=()=>{const panel=$('#posNewSection');if(panel){panel.classList.toggle('hidden');if(!panel.classList.contains('hidden'))$('#posNewName')?.focus()}};
}
function collectPointOfSaleSettings(){const rows=[...document.querySelectorAll('[data-pos-row]')];const changes=new Map(rows.map(r=>[r.querySelector('[data-pos-id]').value,{id:r.querySelector('[data-pos-id]').value,name:r.querySelector('[data-pos-name]').value.trim(),warehouseId:r.querySelector('[data-pos-wh]').value,address:r.querySelector('[data-pos-address]').value.trim(),email:r.querySelector('[data-pos-email]').value.trim(),phone:r.querySelector('[data-pos-phone]').value.trim(),active:r.querySelector('[data-pos-active]').checked}]));const stores=(state.settings.pointsOfSale||[]).map(p=>changes.has(p.id)?{...p,...changes.get(p.id)}:p);if(stores.some(x=>!x.name||!x.warehouseId))throw new Error('Completa nome e magazzino per ogni punto vendita.');if(stores.some(x=>x.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.email)))throw new Error('Controlla gli indirizzi email.');return stores}
export function bindSettingsBranding(){
  const faviconData=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const size=256,c=document.createElement('canvas');c.width=size;c.height=size;const ctx=c.getContext('2d');ctx.clearRect(0,0,size,size);const k=Math.min(size/img.width,size/img.height);const w=Math.round(img.width*k),h=Math.round(img.height*k);ctx.drawImage(img,Math.round((size-w)/2),Math.round((size-h)/2),w,h);resolve(c.toDataURL('image/png'))};img.onerror=reject;img.src=r.result};r.onerror=reject;r.readAsDataURL(file)});
  const bindFile=(id,key,size=700)=>{const input=$(id);if(input&&!input.dataset.bound){input.dataset.bound='1';input.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;state.settings[key]=key==='appFavicon'?await faviconData(f):await compressImage(f,size,.84);renderSettings()})}};
  bindFile('#setAppLogoFile','appLogo',700);bindFile('#setLoginLogoFile','loginLogo',700);bindFile('#setReceiptLogoFile','receiptLogo',700);bindFile('#setFaviconFile','appFavicon',256);
  [['#removeAppLogo','appLogo'],['#removeLoginLogo','loginLogo'],['#removeReceiptLogo','receiptLogo'],['#removeFavicon','appFavicon']].forEach(([id,key])=>{const b=$(id);if(b&&!b.dataset.bound){b.dataset.bound='1';b.onclick=()=>{state.settings[key]='';renderSettings()}}})
}
